function teammateInsight(name){let pairs=new Map;data.matches.filter(x=>x.result!=='P').forEach(x=>{let side=x.a.includes(name)?'A':x.b.includes(name)?'B':null;if(!side)return;let team=side==='A'?x.a:x.b,w=x.result===side;team.filter(n=>n!==name).forEach(n=>{let r=pairs.get(n)||{games:0,wins:0};r.games++;if(w)r.wins++;pairs.set(n,r)})});return[...pairs].map(([teammate,r])=>({teammate,...r,rate:Math.round(r.wins/r.games*100)})).sort((a,b)=>b.rate-a.rate||b.games-a.games)[0]}
