const navigationStateKey='fives-navigation-state';
function savedNavigation(){try{return JSON.parse(sessionStorage.getItem(navigationStateKey))||{}}catch{return{}}}
function saveNavigation(patch={}){try{sessionStorage.setItem(navigationStateKey,JSON.stringify({...savedNavigation(),...patch}))}catch{}}
function activatePage(page,save=true){if(!document.getElementById(page))page='classement';$$('.tab').forEach(tab=>tab.classList.toggle('active',tab.dataset.page===page));$$('.page').forEach(section=>section.classList.toggle('active',section.id===page));if(page==='composer')drawComposer();if(save)saveNavigation({page})}
function activatePlayerView(view,save=true){if(!['cards','analytics','best-five','compare'].includes(view))view='cards';$$('.subtab').forEach(tab=>tab.classList.toggle('active',tab.dataset.playerView===view));$('#playerCardsView').classList.toggle('active',view==='cards');$('#playerAnalyticsView').classList.toggle('active',view==='analytics');$('#bestFiveView').classList.toggle('active',view==='best-five');$('#playerCompareView').classList.toggle('active',view==='compare');$('#playerViewToggle').hidden=view!=='cards';if(view==='analytics')renderPlayerAnalytics();if(view==='best-five')renderBestFive(stats());if(view==='compare')renderPlayerComparison();if(save)saveNavigation({playerView:view})}
