function restoreScrollPosition(){let y=+savedNavigation().scrollY||0,restore=()=>scrollTo({top:y,left:0,behavior:'instant'});requestAnimationFrame(()=>requestAnimationFrame(restore));setTimeout(restore,250)}
function closeDialog(d){d.close();if(d.id==='videoDialog')$('#matchVideoFrame').src='';if(d.id==='matchDialog')resetMatch();if(d.id==='playerDialog'){if(cloud&&pendingAvatarPath&&!pendingPlayerSaved)db.storage.from(avatarBucket).remove([pendingAvatarPath]);pendingPlayerId=null;pendingAvatarPath=null;pendingPlayerSaved=false;$('#playerDialog form').reset();resetAvatarDrop($('#newAvatarDrop'))}}
$$('.close').forEach(b=>b.onclick=()=>closeDialog(b.closest('dialog')));$$('dialog').forEach(d=>d.onclick=e=>{if(e.target===d)closeDialog(d)});
