function moveCompose(n,to){composeSheet=composeSheet.filter(x=>x!==n);if(to==='sheet')composeSheet.push(n);drawComposer()}
function moveManual(n,to){composeManual.A=composeManual.A.filter(x=>x!==n);composeManual.B=composeManual.B.filter(x=>x!==n);if(to==='A'||to==='B')composeManual[to].push(n);drawComposer()}
function drawComposer(){if(!$('#composeBench'))return;let manual=composeMode==='manual';$('#autoSelectionBoard').hidden=manual;$('#autoSelectionBoard').style.display=manual?'none':'';$('#manualSelectionBoard').hidden=!manual;$('#manualSelectionBoard').style.display=manual?'':'none';$('#generateTeamsBtn').textContent=manual?(language==='fr'?'Calculer le pronostic':'Calculate prediction'):tr('generateTeams');$('#composerInstructions').textContent=manual?(language==='fr'?'Glisse les joueurs du banc vers Team A ou Team B, puis calcule le pronostic de ta composition.':'Drag players from the bench to Team A or Team B, then calculate the prediction.'):(language==='fr'?'Place les participants sur la feuille de match, choisis un style, puis laisse le système former les équipes.':'Place participants on the match sheet, choose a style, then let the system build the teams.');if(manual){let bench=data.players.map(p=>p.name).filter(n=>!composeManual.A.includes(n)&&!composeManual.B.includes(n));$('#composeManualBench').innerHTML=$('#composeManualA').innerHTML=$('#composeManualB').innerHTML='';bench.forEach(n=>$('#composeManualBench').append(chip(n,'composeManual','bench')));composeManual.A.forEach(n=>$('#composeManualA').append(chip(n,'composeManual','A')));composeManual.B.forEach(n=>$('#composeManualB').append(chip(n,'composeManual','B')));$('#manualBenchCount').textContent=bench.length;$('#manualTeamACount').textContent=composeManual.A.length;$('#manualTeamBCount').textContent=composeManual.B.length;return}let bench=data.players.map(p=>p.name).filter(n=>!composeSheet.includes(n));$('#composeBench').innerHTML=$('#composeSheet').innerHTML='';bench.forEach(n=>$('#composeBench').append(chip(n,'compose','bench')));composeSheet.forEach(n=>$('#composeSheet').append(chip(n,'compose','sheet')));$('#benchCount').textContent=bench.length;$('#sheetCount').textContent=composeSheet.length}
function profileCounts(team){let keys=['attaque','milieu','defense','gardien','polyvalent'],counts=Object.fromEntries(keys.map(k=>[k,0]));team.forEach(n=>counts[player(n)?.position||'polyvalent']++);return counts}
function profilePenalty(A,B){let ca=profileCounts(A),cb=profileCounts(B),weights={attaque:9,milieu:7,defense:10,gardien:16,polyvalent:4},penalty=0;Object.keys(weights).forEach(k=>{let total=ca[k]+cb[k],gap=Math.abs(ca[k]-cb[k]);penalty+=gap*weights[k];if(total>=2&&(!ca[k]||!cb[k]))penalty+=weights[k]*(k==='gardien'?4:2)});let attackA=ca.attaque+ca.milieu*.45+ca.polyvalent*.3,attackB=cb.attaque+cb.milieu*.45+cb.polyvalent*.3,defenseA=ca.defense+ca.gardien+ca.milieu*.25+ca.polyvalent*.3,defenseB=cb.defense+cb.gardien+cb.milieu*.25+cb.polyvalent*.3;return penalty+Math.abs(attackA-attackB)*5+Math.abs(defenseA-defenseB)*6}
function balance(A,B,strengths){let teamPower=t=>t.reduce((z,n)=>z+(strengths?.[n]??strength(n)),0),a=teamPower(A)/Math.max(A.length,1),b=teamPower(B)/Math.max(B.length,1),pa=A.reduce((z,n)=>z+pos(player(n)?.position),0),pb=B.reduce((z,n)=>z+pos(player(n)?.position),0);return Math.abs(a-b)+Math.abs(pa-pb)*3+profilePenalty(A,B)+Math.abs(A.length-B.length)*40}
function fair(names){let best,tries=Math.min(5000,Math.max(1200,names.length*350)),strengths=Object.fromEntries(names.map(n=>[n,strength(n)]));for(let i=0;i<tries;i++){let m=shuffle(names),k=Math.ceil(m.length/2),c={A:m.slice(0,k),B:m.slice(k)};c.score=balance(c.A,c.B,strengths);if(!best||c.score<best.score)best=c}return best}
function human(names){if(names.length<4)return random(names);let strengths=Object.fromEntries(names.map(n=>[n,strength(n)])),ranked=[...names].sort((a,b)=>strengths[b]-strengths[a]),best;for(let i=0;i<Math.min(1800,Math.max(500,names.length*150));i++){let pair=i%2?ranked.slice(0,2):ranked.slice(-2),rest=shuffle(ranked.filter(n=>!pair.includes(n))),A=[...pair],B=[];rest.forEach(n=>{let t=A.length>=Math.ceil(names.length/2)?B:B.length>=Math.floor(names.length/2)?A:balance([...A,n],B,strengths)<=balance(A,[...B,n],strengths)?A:B;t.push(n)});let candidate={A,B,score:balance(A,B,strengths)};if(!best||candidate.score<best.score)best=candidate}return best}
